/* ─────────────────────────────────────────────────── */
/* Font selector classes (driven by Style Settings)    */
/* ─────────────────────────────────────────────────── */

body.notion-obsidian-font-fira-sans {
  --font-default: "Fira Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
}

body.notion-obsidian-font-source-sans {
  --font-default: "Source Sans 3", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
}

body.notion-obsidian-font-nunito-sans {
  --font-default: "Nunito Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
}

body.notion-obsidian-font-inter {
  --font-default: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
}

/* Monospace override — Fira Code for all code blocks */
body {
  --font-monospace: "Fira Code", "Consolas", "SFMono-Regular", monospace;
}

/* ─────────────────────────────────────────────────── */
/* Main Theme Styling                                  */
/* ─────────────────────────────────────────────────── */

/*** CODE - FIRA CODE ***/
@font-face { 
  font-family: "Fira Code";
  font-weight: 300 500;
  src: url(data:font/ttf;base64,);
}

/*** INTER ***/
@font-face { 
  font-family: "Inter";
  font-style: normal;
  font-weight: 100 300 400 600 700 800;
  src: url(data:font/ttf;base64,);
}

/*** IBM PLEX ***/
@font-face { 
  font-family: "IBMRegular";
  font-weight: normal;

  src: url(data:font/ttf;base64,);
}

/*** IBM PLEX BOLD ***/
@font-face { 
  font-family: "IBMBold";
  font-weight: bold;
  src: url(data:font/ttf;base64,);
}

/*** IA WRITER QUATTRO ***/
@font-face { 
  font-family: "iaWriterQuattro";
  
  font-weight: normal;
  font-style: normal;
  
  src: url(data:application/octet-stream;base64,);
}


body {

  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  
  /*****
  GENERAL VARIABLES
  *****/
  
  --width-body-content: 1280px;
  --list-indent: .8rem;
  --link-unresolved-opacity: 0.85;

  /*** tags ***/
  --tag-radius: 5px;
  --tag-color: #000;
  --tag-padding: 3px;
  --tag-padding-y: 2px; 
  --tag-padding-x: 6px;

  
  /*** All typos ***/

  --font-smallest: 0.6rem;
  --tag-size: .75rem;
  
  /* Notion-matched heading sizes */
  --size-h1: 1.8rem;
  --size-h2: 1.4rem;
  --size-h3: 1.3rem;
  --size-h4: 1.2rem;
  --size-h5: 1rem;
  --size-h6: 1rem;

  --font-paragraph: 1rem;
  --frontmatter-font-size: .75rem;


  --font-family-inter: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  --font-family-ibm: "IBMRegular", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-family-iawriter-quattro: "iaWriterQuattro", mono;

  /* --font-family-serif: Inter, Helvetica, Arial, sans-serif; */
  --font-family-sans: var(--font-family-inter);
  /* --font-family-serif: Times, Georgia, "Times New Roman", serif; */

  /* Default font — overridden by Style Settings font selector */
  --font-default: "Fira Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;


  /* FIX: table text now matches body text size */
  --table-cell-fontsize: 1rem;
  --table-head-fontsize: 1rem;

  /* Interface (UI) font size — default removed; controlled by Style Settings.
     Fallback value is provided inline via var(--notion-obsidian-ui-font-size, 0.875rem) where used. */

  --ribbon-background: var(--color-base-20);
  --divider-color: var(--color-base-15);

  --tab-radius-active: 0;

  /*** COLORS ***/

  --tab-container-background2: rgba(0,0,0,.07);

}

body.eis-hide-ribbon {
  --frame-left-space: 70px !important;
}

.cm-s-obsidian .HyperMD-codeblock {font-weight: normal;}

/* ─────────────────────────────────────────────────── */
/* INTERFACE FONT SIZE — applies to UI chrome only     */
/* Markdown content sizes are controlled separately    */
/* via --font-paragraph, --size-h1..h6, etc.           */
/* ─────────────────────────────────────────────────── */

/* Apply UI font size directly to interface containers.
   --notion-obsidian-ui-font-size is set by Style Settings (variable-number-slider).
   No !important on the variable itself — that would block Style Settings. */
.workspace-split.mod-left-split,
.workspace-split.mod-right-split,
.workspace-ribbon,
.status-bar,
.workspace-tab-header-container,
.side-dock-settings,
.modal-container,
.menu,
.modal.mod-settings,
.vertical-tab-nav-item,
.setting-item-name,
.setting-item-description,
.setting-item-control,
.vertical-tab-content,
.prompt {
  font-size: var(--notion-obsidian-ui-font-size, 0.875rem) !important;
}

/* Also scale Obsidian's built-in UI size tokens */
.nav-file-title,
.nav-folder-title,
.tree-item-self,
.search-result-file-title,
.search-result-file-match,
.tag-pane-tag,
.backlink-pane .tree-item-inner,
.workspace-tab-header-inner-title,
.view-header-title {
  font-size: var(--notion-obsidian-ui-font-size, 0.875rem) !important;
}

/* Old font classes removed — replaced by notion-obsidian-font-* selectors above */


body.theme-light {
  --color-base-23: #f7f6f3;
}

body.theme-dark {
  --color-base-23: #2f2f2f;
}

body.eis-small-font {
  /* Small font now only affects interface, not markdown content.
     Markdown sizes are controlled via Style Settings heading/paragraph sliders. */
  --notion-obsidian-ui-font-size: 0.825rem;
}


/*****
Preview Mode
*****/

.markdown-rendered div:has( > :is(p,pre,table,ul,ol)) + div > :is(h1) {
    margin-bottom: calc(var(--heading-spacing) + -56px);
    margin-top: calc(var(--heading-spacing) + -10px);
}

.markdown-rendered div:has( > :is(p,pre,table,ul,ol)) + div > :is(h2) {
    margin-bottom: calc(var(--heading-spacing) + -12px);
    margin-top: calc(var(--heading-spacing) + 5px);
}

/*.markdown-rendered div:has( > :is(p,pre,table,ul,ol)) + div > :is(h1,h2,h3,h4,h5,h6) {
  margin: calc(var(--heading-spacing) + 8px) 0 calc(var(--heading-spacing) + -57px) !important;
}*/

.markdown-rendered p {margin-bottom: 28px}

.markdown-rendered .metadata-properties-heading:before {font-size: 10px !important;}

.metadata-container .metadata-add-button {cursor: pointer; transition: all .07s linear;}
.show-properties .metadata-container {padding-bottom: 40px}

.metadata-properties-heading {cursor: pointer;}
.metadata-properties-heading.is-collapsed .metadata-properties-title,
.collapse-indicator.collapse-icon.is-collapsed {opacity: 0.4;}

/*****
Body Lists
*****/
.cm-hmd-list-indent {
  text-indent: 0;
}

.markdown-rendered.show-indentation-guide li > ul::before, .markdown-rendered.show-indentation-guide li > ol::before {border: 0;}

.cm-indent::before {border:0 !important;}

div > ul,
div > ol {
    margin-left: 13px;
}

div > ul ul,
div > ol ol {
    margin-left: 13px;
}

