}

.vertical-tab-nav-item {cursor: pointer;}
.modal.mod-settings .vertical-tab-header {border-right: none;}

/* ─────────────────────────────────────────────────── */
/* TAB BAR HEADER                                      */
/* ─────────────────────────────────────────────────── */

/** scroll bars **/
.eis-showing-scrollbar ::-webkit-scrollbar {
  width: 9px;
}

.eis-showing-scrollbar ::-webkit-scrollbar-track {
  background: var(--scrollbar-background);
}

.eis-showing-scrollbar ::-webkit-scrollbar-thumb {
  background-color: var(--scrollbar-color);
  border-radius: 0;
  border: 0px;
}

.workspace .mod-root .workspace-tab-header {order: 2;}

.eis-small-pinned-tabs .workspace-tab-header:has(.mod-pinned) {
  max-width: 70px !important;
  order: 1;
}

.eis-hide-ribbon .workspace-ribbon.mod-left {display: none;}

/* ─────────────────────────────────────────────────── */
/* Iconize plugin compatibility                        */
/* Hide theme default icons when Iconize provides one  */
/* ─────────────────────────────────────────────────── */
.eis-with-icons .nav-file-title:has(.iconize-icon):before,
.eis-with-icons .nav-folder-title:has(.iconize-icon):before {
  display: none !important;
}

/* ─────────────────────────────────────────────────── */
/* Active tab contrast                                 */
/* ─────────────────────────────────────────────────── */

/* Light theme: active tab gets white bg, inactive stays muted */
body.theme-light .workspace .mod-root .workspace-tab-header {
  background-color: transparent;
  opacity: 0.6;
}
body.theme-light .workspace .mod-root .workspace-tab-header.is-active {
  background-color: #ffffff;
  opacity: 1;
  border-bottom: 2px solid #37352f;
}

/* Dark theme: active tab gets lighter bg, inactive stays muted */
body.theme-dark .workspace .mod-root .workspace-tab-header {
  background-color: transparent;
  opacity: 0.6;
}
body.theme-dark .workspace .mod-root .workspace-tab-header.is-active {
  background-color: rgba(255, 255, 255, 0.08);
  opacity: 1;
  border-bottom: 2px solid #e3e2e0;
}

/* ─────────────────────────────────────────────────── */
/* MAKE.md Plugin custom */
/* ─────────────────────────────────────────────────── */

div.mk-header.cm-line {padding-bottom: 50px !important;}
.mk-header .mk-file-context-file .mk-file-icon,
.mk-header .mk-file-icon button {
  width: 70px; 
  height: 70px;
}

.mk-header .mk-file-context-file .mk-file-icon {
  transform: translate(0, -19px);
}

.mk-header .mk-file-icon button {font-size: 70px;}

/** hidding the inline title of the context option make.md **/
.mk-file-context-file .mk-inline-title.inline-title,
.markdown-source-view.mod-cm6.is-readable-line-width .mk-file-context-file > .mk-inline-title.inline-title {display: none !important;}

.mk-tree-wrapper.mk-section-wrapper > .mk-section .mk-collapse,
.mk-file-context-collapse {left: -25px; top: 95px; cursor: pointer;}
.mk-header .mk-file-context-collapse.mk-collapsed svg {color: rgba(0, 0, 0, .2);}

.mk-collapse.mk-icon-xsmall.mk-file-context-collapse.mk-collapsed:after {
  content: "Collapsed";
  color: rgba(0, 0, 0, .2)
}

.menu {
  border-radius: 3px;
}

.mk-menu-input input {
  width: 100%;
  font-size: 12px;
  line-height: 20px;
  padding: 3px 6px;
  position: relative;
  border-radius: 4px;
  box-shadow: rgba(15, 15, 15, 0.1) 0px 0px 0px 1px inset;
  background: rgba(242, 241, 238, 0.6);
  cursor: text;
  height: 28px;
}

.mk-options-menu__suggestions {overflow-x: hidden;}

.cm-line.mk-placeholder:before {
  font-size: .9rem !important;
  top: 2px;
  cursor: default;
}

body:not(.is-mobile) .mk-tree-wrapper .mk-drag-handle {cursor: grab;}

.mk-tree-item.nav-folder-title.is-active.is-selected,
.mk-tree-item.nav-file-title.is-active.is-selected,
.mk-tree-item.nav-file-title.is-active.is-selected:hover {font-weight: bold;}

.theme-dark .mk-tree-item.nav-folder-title.is-active.is-selected,
.theme-dark .mk-tree-item.nav-file-title.is-active.is-selected {color: #fff;}

.tree-item * {
  font-size: .8rem;
}

